CREATE SCHEMA IF NOT EXISTS app;
CREATE TABLE app.role (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE app.school (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, abbreviation TEXT NOT NULL, address TEXT NOT NULL, street_address TEXT NOT NULL, city TEXT, state TEXT, postal_code TEXT, country TEXT DEFAULT 'USA', is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE app.account (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL REFERENCES app.school(id), first_name TEXT NOT NULL, last_name TEXT NOT NULL, middle_name TEXT, email TEXT NOT NULL UNIQUE, phone_number TEXT NOT NULL, role_id BIGINT NOT NULL REFERENCES app.role(id), is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE app.course (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, abbreviation TEXT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT course_dates_check CHECK (start_date < end_date));
CREATE TABLE app.roster (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id BIGINT NOT NULL REFERENCES app.school(id), account_id BIGINT NOT NULL REFERENCES app.account(id), course_id BIGINT NOT NULL REFERENCES app.course(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(school_id, account_id, course_id));
CREATE TABLE app.standard (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, short_name TEXT NOT NULL, reference_ids TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE app.assessment_unit (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id BIGINT NOT NULL REFERENCES app.course(id), name TEXT NOT NULL, abbreviation TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE app.assessment_unit_standard (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assessment_unit_id BIGINT NOT NULL REFERENCES app.assessment_unit(id), standard_id BIGINT NOT NULL REFERENCES app.standard(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(assessment_unit_id, standard_id));
CREATE TABLE app.assessment (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assessment_unit_id BIGINT NOT NULL REFERENCES app.assessment_unit(id), name TEXT NOT NULL, scoring_scale TEXT NOT NULL, max_score NUMERIC NOT NULL, min_score NUMERIC NOT NULL, default_score NUMERIC NOT NULL, placeholder_score NUMERIC NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT assessment_scoring_scale_check CHECK (scoring_scale IN ('free-numeric','two-value','three-value','four-value','five-value')));
CREATE TABLE app.assessment_standard (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assessment_id BIGINT NOT NULL REFERENCES app.assessment(id), standard_id BIGINT NOT NULL REFERENCES app.standard(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(assessment_id, standard_id));
CREATE TABLE app.assignment (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, roster_id BIGINT NOT NULL REFERENCES app.roster(id), assessment_id BIGINT NOT NULL REFERENCES app.assessment(id), score NUMERIC, attempt_number INTEGER NOT NULL DEFAULT 1, completed_at TIMESTAMPTZ, version INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(roster_id, assessment_id, attempt_number));
CREATE INDEX account_role_idx ON app.account(role_id);
CREATE INDEX roster_school_idx ON app.roster(school_id); CREATE INDEX roster_account_idx ON app.roster(account_id); CREATE INDEX roster_course_idx ON app.roster(course_id);
CREATE INDEX assessment_unit_course_idx ON app.assessment_unit(course_id);
CREATE INDEX aus_unit_idx ON app.assessment_unit_standard(assessment_unit_id); CREATE INDEX aus_standard_idx ON app.assessment_unit_standard(standard_id);
CREATE INDEX assessment_unit_idx ON app.assessment(assessment_unit_id);
CREATE INDEX as_assessment_idx ON app.assessment_standard(assessment_id); CREATE INDEX as_standard_idx ON app.assessment_standard(standard_id);
CREATE INDEX assignment_roster_idx ON app.assignment(roster_id); CREATE INDEX assignment_assessment_idx ON app.assignment(assessment_id); CREATE INDEX assignment_roster_assessment_idx ON app.assignment(roster_id, assessment_id);
